"""Module for ConnectionFactory class."""

from .connection import Connection
from .connection_uds import ConnectionUDS


class ConnectionFactory:
    """ConnectionFactory class."""

    @staticmethod
    def create(virtual_connection: bool = False):
        """Provide proper connection object for handling ncc operations under virtual and hw connection.

        :param virtual_connection: indicates whether virtual connection should be used.
        """
        return ConnectionUDS if virtual_connection else Connection
